-- Pre-2025 café revenue history: a daily-grain archive source for unified_sales.
--
-- WHY THIS EXISTS
-- The database's café till history begins 2025-01-01 (the earliest hubbo_sales
-- row). That floor is an IMPORT BOUNDARY, not a business start — Jan 2025 is a
-- full steady month (Putrajaya RM67,606 / Shah Alam RM96,961), not a new-store
-- ramp, so both outlets were trading well before it and that history was simply
-- never imported. Any "revenue since <year>" question earlier than 2025 could
-- not be answered from SQL at all; it had to be answered by hand out of Google
-- Drive. This table closes that gap for 2024.
--
-- SOURCE + FIDELITY
-- Rows are digitised from the owner's "Celsius - Sales Tracking 2024" sheet
-- (Drive id 1NxHDK1k6cFFKbBbTYmuOgCqACVH94c8feLk6iaGQNbk), Daily tab, read at
-- full stored precision — NOT the display-rounded values, which drift the annual
-- total by RM4–20 per outlet. Every month reconciles to the cent against that
-- workbook's own Monthly tab, and the annual totals land exactly on its Overall
-- row: Putrajaya 828,906.52 and Shah Alam 774,642.52.
-- The sheet is trustworthy as a lens: where it overlaps unified_sales (2025
-- Jan–Apr) it agrees with hubbo_sales cent-for-cent, so it is the same till
-- data recorded by hand a year earlier.
--
-- KNOWN LIMITATIONS (deliberate, documented rather than papered over)
--   • DAILY GRAIN, not receipts. Like consignment_sales, one row per outlet-day.
--     `item_count` is the sheet's order count, so AOV is a true per-order
--     average, but there is no per-receipt, per-hour or per-tender detail.
--     Anything hour-of-day (the ads window, labour gate shaping) must not read
--     these rows expecting a distribution.
--   • ONE CHANNEL BUCKET. The sheet recorded a single daily Sales figure per
--     outlet, so the whole amount maps to source='till'. If those outlets ran
--     GrabFood in 2024, its revenue is inside these numbers and cannot be split
--     out — 2024 channel breakdowns will read 100% till for these two outlets.
--   • NO DISCOUNT SPLIT. gross = nett; the organic-vs-discounted decomposition
--     the ads work relies on is unavailable before 2025.
--   • 2024 ONLY. There is no 2023/2022/2021 tracking sheet (Drive-searched), and
--     the 2023 artefact is a Bukku GL Sales-account ledger with a single Account
--     and a single Split Account — no outlet dimension, so it cannot be
--     decomposed per outlet at any fidelity. Tamarind opened Aug 2025 and its
--     history is already complete in unified_sales; it has nothing to backfill.
--
-- NO DOUBLE-COUNT: a CHECK constraint pins biz_date strictly before 2025-01-01
-- and the view branch repeats the same bound, so these rows can never overlap
-- the hubbo/storehub/pos_native/pickup eras even if someone loads more later.

CREATE TABLE IF NOT EXISTS historical_daily_sales (
  id          text PRIMARY KEY,
  outlet_id   text NOT NULL REFERENCES "Outlet"(id),
  biz_date    date NOT NULL,
  item_count  integer NOT NULL DEFAULT 0,
  nett        numeric(12,2) NOT NULL,
  source_ref  text NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT historical_daily_sales_pre_2025
    CHECK (biz_date < DATE '2025-01-01'),
  CONSTRAINT historical_daily_sales_nett_nonneg
    CHECK (nett >= 0),
  CONSTRAINT historical_daily_sales_outlet_day UNIQUE (outlet_id, biz_date)
);

COMMENT ON TABLE historical_daily_sales IS
  'Daily-grain café revenue predating the hubbo till import (2025-01-01). Hand-digitised from the owner''s "Celsius - Sales Tracking" Drive sheets; SQL-managed like consignment_sales, deliberately NOT in schema.prisma. See migration 20260730_historical_daily_sales.';
COMMENT ON COLUMN historical_daily_sales.nett IS
  'Whole-day takings in RM as the sheet recorded them: net of discounts, all channels combined. gross/sst/discount are unavailable at this grain.';
COMMENT ON COLUMN historical_daily_sales.source_ref IS
  'Provenance of the row, e.g. "sheet:Celsius - Sales Tracking 2024" — surfaced as unified_sales.order_ref so any figure can be traced back.';

CREATE INDEX IF NOT EXISTS historical_daily_sales_outlet_date_idx
  ON historical_daily_sales (outlet_id, biz_date);

-- Days the outlet did not trade are ABSENT, not zero. The sheet records a shut
-- day two ways — blank/dash (9–11 Apr fleet-wide for Raya, Putrajaya 28 Mar,
-- both outlets 17 Jun) and an explicit 0 against 0 orders (Putrajaya 26 Sep) —
-- and both are omitted here. Loading them as zero would drag every daily average
-- down by a day the shop was shut. So 722 rows cover 360 Putrajaya trading days
-- + 362 Shah Alam trading days out of 366 calendar days, and the annual totals
-- are unaffected.
ON CONFLICT (outlet_id, biz_date) DO NOTHING;

-- Extend the canonical revenue view with the historical branch. Column list,
-- order and types are unchanged (CREATE OR REPLACE requires that); this only
-- appends a UNION ALL arm, mirroring the consignment arm's daily-grain shape.
CREATE OR REPLACE VIEW unified_sales AS
 SELECT 'hubbo'::text AS source,
    h.id::text AS sale_id,
    h.outlet_id,
    o.name AS outlet_name,
    h.transaction_time AS txn_at,
    (h.transaction_time AT TIME ZONE 'Asia/Kuala_Lumpur'::text)::date AS biz_date,
    h.invoice_no AS order_ref,
    h.item_count,
    h.gross,
    h.discount,
    h.sst,
    h.nett,
    h.tender,
    'counter'::text AS channel,
    h.status,
    h.is_refund
   FROM hubbo_sales h
     JOIN "Outlet" o ON o.id = h.outlet_id
  WHERE h.transaction_time <
        CASE h.outlet_id
            WHEN '89b19c9f-b1e0-42fe-a404-6d1a472e34c5'::text THEN '2026-01-02 16:00:00+00'::timestamp with time zone
            WHEN 'b3b6299e-09dc-4f4a-80ef-bbc04316d324'::text THEN '2026-01-20 16:00:00+00'::timestamp with time zone
            ELSE '2099-12-31 16:00:00+00'::timestamp with time zone
        END
UNION ALL
 SELECT 'storehub'::text AS source,
    s.id::text AS sale_id,
    s.outlet_id,
    o.name AS outlet_name,
    s.transaction_time AS txn_at,
    (s.transaction_time AT TIME ZONE 'Asia/Kuala_Lumpur'::text)::date AS biz_date,
    s.ref_id AS order_ref,
    s.item_count,
    s.sub_total AS gross,
    s.sub_total - s.total AS discount,
    NULL::numeric AS sst,
    s.total AS nett,
    NULL::text AS tender,
    COALESCE(s.channel_class, s.channel) AS channel,
    s.status,
    COALESCE(s.is_cancelled, false) OR lower(COALESCE(s.transaction_type, ''::text)) ~~ '%refund%'::text AS is_refund
   FROM storehub_sales s
     JOIN "Outlet" o ON o.id = s.outlet_id
  WHERE s.transaction_time >=
        CASE s.outlet_id
            WHEN '89b19c9f-b1e0-42fe-a404-6d1a472e34c5'::text THEN '2026-01-02 16:00:00+00'::timestamp with time zone
            WHEN 'b3b6299e-09dc-4f4a-80ef-bbc04316d324'::text THEN '2026-01-20 16:00:00+00'::timestamp with time zone
            ELSE '1899-12-31 16:00:00+00'::timestamp with time zone
        END AND s.transaction_time <
        CASE s.outlet_id
            WHEN '89b19c9f-b1e0-42fe-a404-6d1a472e34c5'::text THEN '2026-06-07 16:00:00+00'::timestamp with time zone
            WHEN 'b3b6299e-09dc-4f4a-80ef-bbc04316d324'::text THEN '2026-06-14 16:00:00+00'::timestamp with time zone
            WHEN '5d1f2731-1985-4e54-a6df-3990e7d5c159'::text THEN '2026-06-17 16:00:00+00'::timestamp with time zone
            ELSE '2099-12-31 16:00:00+00'::timestamp with time zone
        END
UNION ALL
 SELECT 'pos_native'::text AS source,
    p.id AS sale_id,
    m.canonical_id AS outlet_id,
    o.name AS outlet_name,
    p.created_at AS txn_at,
    (p.created_at AT TIME ZONE 'Asia/Kuala_Lumpur'::text)::date AS biz_date,
    p.order_number AS order_ref,
    ( SELECT COALESCE(sum(i.quantity), 0::bigint)::integer AS "coalesce"
           FROM pos_order_items i
          WHERE i.order_id = p.id) AS item_count,
    p.subtotal::numeric / 100.0 AS gross,
    COALESCE(p.discount_amount, 0)::numeric / 100.0 AS discount,
    p.sst_amount::numeric / 100.0 AS sst,
    p.total::numeric / 100.0 AS nett,
    ( SELECT string_agg(DISTINCT pay.payment_method, '+'::text) AS string_agg
           FROM pos_order_payments pay
          WHERE pay.order_id = p.id) AS tender,
    COALESCE(p.source, p.order_type) AS channel,
    p.status,
    p.refund_of_order_id IS NOT NULL AS is_refund
   FROM pos_orders p
     JOIN ( VALUES ('outlet-con'::text,'89b19c9f-b1e0-42fe-a404-6d1a472e34c5'::text), ('outlet-sa'::text,'b3b6299e-09dc-4f4a-80ef-bbc04316d324'::text), ('outlet-tam'::text,'5d1f2731-1985-4e54-a6df-3990e7d5c159'::text)) m(slug, canonical_id) ON m.slug = p.outlet_id
     JOIN "Outlet" o ON o.id = m.canonical_id
  WHERE p.created_at >=
        CASE m.canonical_id
            WHEN '89b19c9f-b1e0-42fe-a404-6d1a472e34c5'::text THEN '2026-06-07 16:00:00+00'::timestamp with time zone
            WHEN 'b3b6299e-09dc-4f4a-80ef-bbc04316d324'::text THEN '2026-06-14 16:00:00+00'::timestamp with time zone
            WHEN '5d1f2731-1985-4e54-a6df-3990e7d5c159'::text THEN '2026-06-17 16:00:00+00'::timestamp with time zone
            ELSE '1899-12-31 16:00:00+00'::timestamp with time zone
        END
UNION ALL
 SELECT 'consignment'::text AS source,
    cs.id AS sale_id,
    cs.outlet_id,
    o.name AS outlet_name,
    ((cs.biz_date + '12:00:00'::time without time zone) AT TIME ZONE 'Asia/Kuala_Lumpur'::text) AS txn_at,
    cs.biz_date,
    cs.source_file AS order_ref,
    cs.item_count,
    cs.gross,
    0::numeric AS discount,
    0::numeric AS sst,
    cs.gross AS nett,
    NULL::text AS tender,
    'counter'::text AS channel,
    'SUCCESS'::text AS status,
    false AS is_refund
   FROM consignment_sales cs
     JOIN "Outlet" o ON o.id = cs.outlet_id
UNION ALL
 SELECT 'historical'::text AS source,
    hd.id AS sale_id,
    hd.outlet_id,
    o.name AS outlet_name,
    ((hd.biz_date + '12:00:00'::time without time zone) AT TIME ZONE 'Asia/Kuala_Lumpur'::text) AS txn_at,
    hd.biz_date,
    hd.source_ref AS order_ref,
    hd.item_count,
    hd.nett AS gross,
    0::numeric AS discount,
    0::numeric AS sst,
    hd.nett,
    NULL::text AS tender,
    'counter'::text AS channel,
    'SUCCESS'::text AS status,
    false AS is_refund
   FROM historical_daily_sales hd
     JOIN "Outlet" o ON o.id = hd.outlet_id
  WHERE hd.biz_date < DATE '2025-01-01'
UNION ALL
 SELECT 'pickup'::text AS source,
    ord.id::text AS sale_id,
    ol.id AS outlet_id,
    ol.name AS outlet_name,
    ord.created_at AS txn_at,
    (ord.created_at AT TIME ZONE 'Asia/Kuala_Lumpur'::text)::date AS biz_date,
    ord.order_number AS order_ref,
    ( SELECT COALESCE(sum(oi.quantity), 0::bigint)::integer AS "coalesce"
           FROM order_items oi
          WHERE oi.order_id = ord.id) AS item_count,
    ord.subtotal::numeric / 100.0 AS gross,
    (COALESCE(ord.promo_discount, 0) + COALESCE(ord.reward_discount_amount, 0) + COALESCE(ord.first_order_discount_amount, 0))::numeric / 100.0 AS discount,
    ord.sst_amount::numeric / 100.0 AS sst,
    ord.total::numeric / 100.0 AS nett,
    ord.payment_method AS tender,
    'pickup'::text AS channel,
    ord.status,
    false AS is_refund
   FROM orders ord
     JOIN "Outlet" ol ON ol."pickupStoreId" = ord.store_id
  WHERE ord.status = ANY (ARRAY['paid'::text, 'preparing'::text, 'ready'::text, 'collected'::text, 'completed'::text]);
